mapper.update:
UPDATE shop_erp_inventory
SET locked_stock = locked_stock + #{quantity},
    version      = version + 1
WHERE sku_id = #{skuId}
  AND warehouse_id = #{warehouseId}
  AND is_deleted = 0
  AND (stock - locked_stock) >= #{quantity}

UPDATE shop_erp_inventory
SET locked_stock = locked_stock - #{quantity},
    version      = version + 1
WHERE sku_id = #{skuId}
  AND warehouse_id = #{warehouseId}
  AND is_deleted = 0
  AND locked_stock >= #{quantity}
